pub fn runtime_boxed_abi(symbol: &str, arity: usize) -> Option<&'static RuntimeBoxedAbi> {
    let index = RUNTIME_BOXED_ABIS
        .binary_search_by_key(&symbol, |abi| abi.symbol)
        .ok()?;
    let abi = &RUNTIME_BOXED_ABIS[index];
    (abi.arity == arity).then_some(abi)
}

/// Explicitly admitted positional op calls; every target consumes this mapping.
pub const RUNTIME_BOXED_OP_KINDS: &[crate::OpKind] = &[
    crate::OpKind::BytearrayCount,
    crate::OpKind::BytearrayCountSlice,
    crate::OpKind::BytearrayEndswith,
    crate::OpKind::BytearrayEndswithSlice,
    crate::OpKind::BytearrayFind,
    crate::OpKind::BytearrayFindSlice,
    crate::OpKind::BytearrayStartswith,
    crate::OpKind::BytearrayStartswithSlice,
    crate::OpKind::BytesCount,
    crate::OpKind::BytesCountSlice,
    crate::OpKind::BytesEndswith,
    crate::OpKind::BytesEndswithSlice,
    crate::OpKind::BytesFind,
    crate::OpKind::BytesFindSlice,
    crate::OpKind::BytesStartswith,
    crate::OpKind::BytesStartswithSlice,
    crate::OpKind::StringCount,
    crate::OpKind::StringCountSlice,
    crate::OpKind::StringEndswith,
    crate::OpKind::StringEndswithSlice,
    crate::OpKind::StringFind,
    crate::OpKind::StringFindSlice,
    crate::OpKind::StringStartswith,
    crate::OpKind::StringStartswithSlice,
];

pub fn runtime_boxed_op_abi(kind: crate::OpKind) -> Option<&'static RuntimeBoxedAbi> {
    match kind {
        crate::OpKind::BytearrayCount => Some(RuntimeFn::BytearrayCount.boxed_abi()),
        crate::OpKind::BytearrayCountSlice => Some(RuntimeFn::BytearrayCountSlice.boxed_abi()),
        crate::OpKind::BytearrayEndswith => Some(RuntimeFn::BytearrayEndswith.boxed_abi()),
        crate::OpKind::BytearrayEndswithSlice => {
            Some(RuntimeFn::BytearrayEndswithSlice.boxed_abi())
        }
        crate::OpKind::BytearrayFind => Some(RuntimeFn::BytearrayFind.boxed_abi()),
        crate::OpKind::BytearrayFindSlice => Some(RuntimeFn::BytearrayFindSlice.boxed_abi()),
        crate::OpKind::BytearrayStartswith => Some(RuntimeFn::BytearrayStartswith.boxed_abi()),
        crate::OpKind::BytearrayStartswithSlice => {
            Some(RuntimeFn::BytearrayStartswithSlice.boxed_abi())
        }
        crate::OpKind::BytesCount => Some(RuntimeFn::BytesCount.boxed_abi()),
        crate::OpKind::BytesCountSlice => Some(RuntimeFn::BytesCountSlice.boxed_abi()),
        crate::OpKind::BytesEndswith => Some(RuntimeFn::BytesEndswith.boxed_abi()),
        crate::OpKind::BytesEndswithSlice => Some(RuntimeFn::BytesEndswithSlice.boxed_abi()),
        crate::OpKind::BytesFind => Some(RuntimeFn::BytesFind.boxed_abi()),
        crate::OpKind::BytesFindSlice => Some(RuntimeFn::BytesFindSlice.boxed_abi()),
        crate::OpKind::BytesStartswith => Some(RuntimeFn::BytesStartswith.boxed_abi()),
        crate::OpKind::BytesStartswithSlice => Some(RuntimeFn::BytesStartswithSlice.boxed_abi()),
        crate::OpKind::StringCount => Some(RuntimeFn::StringCount.boxed_abi()),
        crate::OpKind::StringCountSlice => Some(RuntimeFn::StringCountSlice.boxed_abi()),
        crate::OpKind::StringEndswith => Some(RuntimeFn::StringEndswith.boxed_abi()),
        crate::OpKind::StringEndswithSlice => Some(RuntimeFn::StringEndswithSlice.boxed_abi()),
        crate::OpKind::StringFind => Some(RuntimeFn::StringFind.boxed_abi()),
        crate::OpKind::StringFindSlice => Some(RuntimeFn::StringFindSlice.boxed_abi()),
        crate::OpKind::StringStartswith => Some(RuntimeFn::StringStartswith.boxed_abi()),
        crate::OpKind::StringStartswithSlice => Some(RuntimeFn::StringStartswithSlice.boxed_abi()),
        _ => None,
    }
}
